      createCipheriv,
      createDecipheriv,
      randomBytes,
    } = await import('node:crypto');

    const key = 'keykeykeykeykeykeykeykey';
    const nonce = randomBytes(12);

    const aad = Buffer.from('0123456789', 'hex');

