import { NextAuthOptions } from 'next-auth';
import { Adapter } from 'next-auth/adapters';
import CredentialsProvider from 'next-auth/providers/credentials';
import { PrismaAdapter } from '@auth/prisma-adapter';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { clearAuthRateLimit, consumeAuthRateLimit } from '@/lib/authRateLimit';
import {
    getTrustedClientAddressFromHeaders,
    hasTrustedProxyConfiguration
} from '@/lib/clientAddress';

// A valid bcrypt hash of a throwaway value, used only to equalize response
// timing when no matching user exists (anti-enumeration). It is never a real
// credential and never matches any user-supplied password.
const DUMMY_PASSWORD_HASH = '$2b$10$m5cSUIfLL/REDACTED.YOCKKxBtS';

export const authOptions: NextAuthOptions = {
    // @auth/prisma-adapter is typed against @auth/core's Adapter, which is
    // structurally compatible with next-auth v4's Adapter but nominally distinct.
    adapter: PrismaAdapter(prisma) as Adapter,
    providers: [
        CredentialsProvider({
            name: 'Credentials',
            credentials: {
                email: { label: 'Email', type: 'email', placeholder: 'user@example.com' },
                password: { label: 'Password', type: 'password' },
            },
            async authorize(credentials, request) {
                // Single generic message for every failure mode so the response
                // never reveals whether an account with this email exists.
                const INVALID = 'Invalid email or password';

                if (!credentials?.email || !credentials?.password) {
                    throw new Error(INVALID);
                }

                const email = credentials.email.trim().toLowerCase();
                const clientAddress = getTrustedClientAddressFromHeaders(request?.headers);
                if (hasTrustedProxyConfiguration() && !clientAddress) throw new Error(INVALID);
                if (clientAddress) {
                    const sourceLimit = await consumeAuthRateLimit('login-source', clientAddress, {
                        limit: 20,
                        windowSeconds: 15 * 60,
                    });
                    if (!sourceLimit.allowed) throw new Error(INVALID);
                }
                await consumeAuthRateLimit('login-email', email, {
                    limit: 5,
                    windowSeconds: 15 * 60,
                });

                const user = await prisma.user.findUnique({
                    where: { email },
                });

                // Always run a bcrypt comparison — against the real hash when the
                // user exists, otherwise a dummy — so response time does not leak
                // account existence (timing-based enumeration).
                const passwordHash = user?.password ?? DUMMY_PASSWORD_HASH;
                const isPasswordValid = await bcrypt.compare(credentials.password, passwordHash);

                if (!user || !user.password || !user.emailVerified || !isPasswordValid) {
                    throw new Error(INVALID);
                }

                await clearAuthRateLimit('login-email', email);

                // Return only non-sensitive fields (never the password hash).
                return {
                    id: user.id,
                    email: user.email,
                    name: user.name,
                    image: user.image,
                    role: user.role,
                    authVersion: user.authVersion,
                };
            },
        }),
    ],
    session: {
        strategy: 'jwt',
    },
    pages: {
        signIn: '/login', // User custom login page
        newUser: '/signup' // New users directed to sign up page
    },
    callbacks: {
        async jwt({ token, user, account }) {
            if (user) {
                token.id = user.id;
                token.role = user.role;
                token.authVersion = user.authVersion;
                token.invalidated = false;
            } else if (token.id) {
                const currentUser = await prisma.user.findUnique({
                    where: { id: token.id },
                    select: { role: true, authVersion: true, emailVerified: true },
                });
                token.invalidated = !currentUser
                    || !currentUser.emailVerified
                    || currentUser.authVersion !== token.authVersion;
                if (currentUser && !token.invalidated) {
                    token.role = currentUser.role;
                }
            }
            return token;
        },
        async session({ session, token }) {
            if (token.invalidated) return null as unknown as typeof session;
            if (session.user) {
                session.user.id = token.id;
                session.user.role = token.role;
            }
            return session;
        },
    },
};
import { withAuth } from 'next-auth/middleware';

export default withAuth({
    callbacks: {
        authorized: ({ req, token }) => {
            // Protect admin routes to only users with 'ADMIN' role
            if (req.nextUrl.pathname.startsWith('/admin')) {
                return token?.role === 'ADMIN';
            }
            // Require authentication for other protected routes
            return !!token;
        },
    },
});

