import { createHash, randomBytes } from 'crypto';
import { Prisma } from '@prisma/client';
import { prisma } from '@/lib/prisma';

export type AuthTokenPurpose = 'verify-email' | 'reset-password';

export function createAuthTokenDigest(token: string): string {
    return createHash('sha256').update(token).digest('hex');
}

async function pruneExpiredAuthTokenBatch(
    client: Prisma.TransactionClient | typeof prisma,
    limit: number
): Promise<number> {
    return client.$executeRaw(Prisma.sql`
        WITH expired AS (
            SELECT "token"
            FROM "VerificationToken"
            WHERE "expires" <= CURRENT_TIMESTAMP
            ORDER BY "expires" ASC
            LIMIT ${limit}
        )
        DELETE FROM "VerificationToken"
        WHERE "token" IN (SELECT "token" FROM expired)
    `);
}

export async function pruneExpiredAuthTokens(limit = 250): Promise<number> {
    if (!Number.isInteger(limit) || limit < 1) {
        throw new Error('Cleanup limit must be a positive integer.');
    }
    return pruneExpiredAuthTokenBatch(prisma, limit);
}

export async function hasUsableAuthToken(
    purpose: AuthTokenPurpose,
    rawToken: string
): Promise<boolean> {
    const record = await prisma.verificationToken.findUnique({
        where: { token: createAuthTokenDigest(rawToken) },
        select: { identifier: true, expires: true },
    });
    return Boolean(
        record
        && record.identifier.startsWith(`${purpose}:`)
        && record.expires > new Date()
    );
}

export async function issueAuthToken(
    purpose: AuthTokenPurpose,
    emailAddress: string,
    lifetimeSeconds: number
): Promise<string> {
    if (!Number.isInteger(lifetimeSeconds) || lifetimeSeconds < 1) {
        throw new Error('Token lifetime must be a positive integer.');
    }

    const email = emailAddress.trim().toLowerCase();
    const identifier = `${purpose}:${email}`;
    const token = randomBytes(32).toString('base64url');
    const expires = new Date(Date.now() + lifetimeSeconds * 1_000);

    await prisma.$transaction(async transaction => {
        await pruneExpiredAuthTokenBatch(transaction, 100);
        await transaction.verificationToken.deleteMany({ where: { identifier } });
        await transaction.verificationToken.create({
            data: { identifier, token: createAuthTokenDigest(token), expires }
        });
    });

    return token;
}

export function consumeAuthToken(
    purpose: AuthTokenPurpose,
    rawToken: string
): Promise<string | null>;
export function consumeAuthToken<T>(
    purpose: AuthTokenPurpose,
    rawToken: string,
    operation: (transaction: Prisma.TransactionClient, email: string) => Promise<T>
): Promise<T | null>;
export async function consumeAuthToken<T>(
    purpose: AuthTokenPurpose,
    rawToken: string,
    operation?: (transaction: Prisma.TransactionClient, email: string) => Promise<T>
): Promise<string | T | null> {
    const token = createAuthTokenDigest(rawToken);

    return prisma.$transaction(async transaction => {
        const record = await transaction.verificationToken.findUnique({ where: { token } });
        if (!record) return null;

        const prefix = `${purpose}:`;
        const now = new Date();
        if (!record.identifier.startsWith(prefix) || record.expires <= now) {
            if (record.expires <= now) {
                await transaction.verificationToken.deleteMany({ where: { token } });
            }
            return null;
        }

        const deleted = await transaction.verificationToken.deleteMany({
            where: {
                identifier: record.identifier,
                token,
                expires: { gt: now },
            }
        });
        if (deleted.count !== 1) return null;

        const email = record.identifier.slice(prefix.length);
        return operation ? operation(transaction, email) : email;
    });
}
import { NextResponse } from 'next/server';
import { consumeAuthRateLimit } from '@/lib/authRateLimit';
import {
    getTrustedClientAddressFromHeaders,
    hasTrustedProxyConfiguration,
} from '@/lib/clientAddress';
import {
    authEmailRequestSchema,
    InputValidationError,
    MAX_REGISTRATION_BYTES,
    parseJsonRequest,
    validationErrorPayload,
} from '@/lib/validation';
import { scheduleAfterResponse } from '@/lib/afterResponse';

const ACCEPTED_RESPONSE = {
    message: 'If the account is eligible, an email will be sent shortly.'
};

export async function handleAuthEmailRequest(
    request: Request,
    action: 'verify-request' | 'reset-request',
    operation: (email: string) => Promise<void>
) {
    try {
        const { email } = await parseJsonRequest(
            request,
            authEmailRequestSchema,
            MAX_REGISTRATION_BYTES
        );
        const clientAddress = getTrustedClientAddressFromHeaders(request.headers);
        if (hasTrustedProxyConfiguration() && !clientAddress) {
            return NextResponse.json({
                error: {
                    code: 'INVALID_CLIENT_SOURCE',
                    message: 'Unable to process this account request.',
                    fields: {},
                }
            }, { status: 400 });
        }

        const emailLimit = await consumeAuthRateLimit(`${action}-email`, email, {
            limit: 3,
            windowSeconds: 60 * 60,
        });
        const sourceLimit = clientAddress
            ? await consumeAuthRateLimit(`${action}-source`, clientAddress, {
                limit: 20,
                windowSeconds: 60 * 60,
            })
            : { allowed: true, retryAfterSeconds: 0 };
        if (!emailLimit.allowed || !sourceLimit.allowed) {
            const retryAfterSeconds = Math.max(
                emailLimit.retryAfterSeconds,
                sourceLimit.retryAfterSeconds
            );
            return NextResponse.json({
                error: {
                    code: 'RATE_LIMITED',
                    message: 'Too many account requests. Please try again later.',
                    fields: {},
                }
            }, {
                status: 429,
                headers: { 'Retry-After': String(retryAfterSeconds) },
            });
        }

        scheduleAfterResponse(async () => {
            try {
                await operation(email);
            } catch {
                // The response remains generic so delivery and account state cannot
                // become an enumeration oracle. Users can safely retry later.
                console.error('Unable to deliver requested authentication email.');
            }
        });
        return NextResponse.json(ACCEPTED_RESPONSE, { status: 202 });
    } catch (error) {
        if (error instanceof InputValidationError) {
            return NextResponse.json(validationErrorPayload(error), {
                status: error.message === 'Request is too large.' ? 413 : 400,
            });
        }
        console.error('Unable to process authentication email request.');
        return NextResponse.json({
            error: {
                code: 'INTERNAL_ERROR',
                message: 'Unable to process this account request right now.',
                fields: {},
            }
        }, { status: 500 });
    }
}
type AuthEmailProvider = 'mailpit' | 'postmark';

function requireSetting(name: string): string {
    const value = process.env[name]?.trim();
    if (!value) throw new Error(`Missing authentication email setting: ${name}`);
    return value;
}

function provider(): AuthEmailProvider {
    const value = requireSetting('AUTH_EMAIL_PROVIDER');
    if (value !== 'mailpit' && value !== 'postmark') {
        throw new Error('AUTH_EMAIL_PROVIDER must be mailpit or postmark');
    }
    return value;
}

function authLink(pathname: string, token: string): string {
    const link = new URL(pathname, requireSetting('NEXTAUTH_URL'));
    if (process.env.AUTH_EMAIL_PROVIDER?.trim() === 'postmark' && link.protocol !== 'https:') {
        throw new Error('Postmark recovery links require an HTTPS application URL.');
    }
    link.hash = new URLSearchParams({ token }).toString();
    return link.toString();
}

function mailpitSender(value: string): { Email: string; Name?: string } {
    const namedAddress = value.match(/^\s*(.*?)\s*<([^<>]+)>\s*$/);
    if (namedAddress) {
        return {
            Email: namedAddress[2].trim(),
            ...(namedAddress[1].trim() ? { Name: namedAddress[1].trim() } : {}),
        };
    }
    return { Email: value };
}

async function sendAuthEmail(input: {
    to: string;
    subject: string;
    introduction: string;
    action: string;
    link: string;
    expiry: string;
}) {
    const text = [
        input.introduction,
        '',
        `${input.action}: ${input.link}`,
        '',
        input.expiry,
        'If you did not request this, you can ignore this email.',
    ].join('\n');
    const selectedProvider = provider();
    const endpoint = requireSetting('AUTH_EMAIL_API_URL');
    const endpointUrl = new URL(endpoint);
    if (selectedProvider === 'postmark' && endpointUrl.protocol !== 'https:') {
        throw new Error('Postmark delivery requires HTTPS.');
    }
    if (selectedProvider === 'postmark'
        && (endpointUrl.hostname !== 'api.postmarkapp.com' || endpointUrl.pathname !== '/email')) {
        throw new Error('Postmark delivery requires the official email API endpoint.');
    }
    const from = requireSetting('AUTH_EMAIL_FROM');
    const headers: Record<string, string> = {
        Accept: 'application/json',
        'Content-Type': 'application/json',
    };
    const body = selectedProvider === 'postmark'
        ? {
            From: from,
            To: input.to,
            Subject: input.subject,
            TextBody: text,
            MessageStream: 'outbound',
        }
        : {
            From: mailpitSender(from),
            To: [{ Email: input.to }],
            Subject: input.subject,
            Text: text,
        };

    if (selectedProvider === 'postmark') {
        headers['X-Postmark-Server-Token'] = requireSetting('AUTH_EMAIL_API_TOKEN');
    }
    const response = await fetch(endpoint, {
        method: 'POST',
        headers,
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) {
        throw new Error(`Authentication email provider rejected delivery (${response.status}).`);
    }
}

export async function sendVerificationEmail(email: string, token: string): Promise<void> {
    await sendAuthEmail({
        to: email,
        subject: 'Verify your Mona Airways email',
        introduction: 'Confirm your email before signing in to Mona Airways.',
        action: 'Verify email',
        link: authLink('/verify-email', token),
        expiry: 'This link expires in 24 hours.',
    });
}

export async function sendPasswordResetEmail(email: string, token: string): Promise<void> {
    await sendAuthEmail({
        to: email,
        subject: 'Reset your Mona Airways password',
        introduction: 'A password reset was requested for your Mona Airways account.',
        action: 'Reset password',
        link: authLink('/reset-password', token),
        expiry: 'This link expires in 1 hour and can be used once.',
    });
}
const AUTH_TOKEN_PATTERN = /^[A-Za-z0-9_-]{43}$/;

export function isValidAuthToken(value: unknown): value is string {
    return typeof value === 'string' && AUTH_TOKEN_PATTERN.test(value);
}

