    revalidatePath('/travelguide');
}

export async function searchFlightsAction(
    from: string,
    to: string,
    departureDateStr?: string,
    returnDateStr?: string,
) {
    const parsed = parseActionInput(searchFlightsSchema, {
        from,
        to,
        departureDate: departureDateStr === '' || departureDateStr === undefined
            ? undefined
            : departureDateStr,
        returnDate: returnDateStr === '' || returnDateStr === undefined
            ? undefined
            : returnDateStr,
    });
    if (!parsed.ok) return parsed;
    // returnDate is validated by the schema (ordering vs. departure) but does
    // not yet constrain the query, so it is intentionally not destructured here.
    ({ from, to, departureDate: departureDateStr } = parsed.data);

    if (!departureDateStr) {
        return await prisma.flight.findMany({
            where: { from, to },
            orderBy: { departureDate: 'asc' },
        });
    }

    const searchDate = new Date(departureDateStr);
    const scheduleService = new FlightScheduleService();
    await scheduleService.generateFlightsForDate(searchDate);

    const dateStr = searchDate.toISOString().split('T')[0];
    const startOfDay = new Date(`${dateStr}T00:00:00.000Z`);
    const endOfDay = new Date(`${dateStr}T23:59:59.999Z`);
    const now = new Date();
    const departureLowerBound = startOfDay <= now
        ? { gt: now }
        : { gte: startOfDay };

    return await prisma.flight.findMany({
        where: {
            from,
            to,
            departureDate: {
                ...departureLowerBound,
                lte: endOfDay
            }
        },
        orderBy: { departureDate: 'asc' },
    });
}

export async function getFlightRoutesAction() {
    const schedules = await prisma.flightSchedule.findMany({
        where: { isActive: true },
        select: {
            from: true,
            to: true,
            departureTime: true,
            daysOfWeek: true,
        },
        orderBy: [{ from: 'asc' }, { to: 'asc' }, { departureTime: 'asc' }],
    });

    return buildFlightRoutes(schedules);
}

export async function bookFlightAction(bookingData: { 
    flightId: number;
    passengers: PassengerInput[];
    idempotencyKey: string;
}) {
export interface FlightScheduleSummary {
    from: string;
    to: string;
    departureTime: string;
    daysOfWeek: number[];
}

export interface FlightRoute {
    from: string;
    to: string;
    nextOperatingDate: string;
}

function getNextDeparture(
    schedule: FlightScheduleSummary,
    now: Date,
): Date | null {
    const timeMatch = /^(\d{2}):(\d{2})$/.exec(schedule.departureTime);
    if (!timeMatch) return null;

    const hours = Number(timeMatch[1]);
    const minutes = Number(timeMatch[2]);
    if (hours > 23 || minutes > 59) return null;

    for (let dayOffset = 0; dayOffset <= 7; dayOffset += 1) {
        const candidate = new Date(Date.UTC(
            now.getUTCFullYear(),
            now.getUTCMonth(),
            now.getUTCDate() + dayOffset,
            hours,
            minutes,
        ));

        if (
            schedule.daysOfWeek.includes(candidate.getUTCDay())
            && candidate.getTime() > now.getTime()
        ) {
            return candidate;
        }
    }

    return null;
}

export function buildFlightRoutes(
    schedules: FlightScheduleSummary[],
    now = new Date(),
): FlightRoute[] {
    const routes = new Map<string, { route: FlightRoute; nextDeparture: Date }>();

    for (const schedule of schedules) {
        const nextDeparture = getNextDeparture(schedule, now);
        if (!nextDeparture) continue;

        const key = `${schedule.from}\u0000${schedule.to}`;
        const current = routes.get(key);
        if (current && current.nextDeparture <= nextDeparture) continue;

        routes.set(key, {
            route: {
                from: schedule.from,
                to: schedule.to,
                nextOperatingDate: nextDeparture.toISOString().slice(0, 10),
            },
            nextDeparture,
        });
    }

    return Array.from(routes.values(), ({ route }) => route);
}
import { prisma } from './prisma';

export default class FlightScheduleService {
    async generateFlightsForDate(date: Date) {
        // Use getUTCDay() to avoid local timezone shifting
        const dayOfWeek = date.getUTCDay(); 

        // Find active schedules that run on this day of the week
        const schedules = await prisma.flightSchedule.findMany({
            where: {
                isActive: true,
                daysOfWeek: {
                    has: dayOfWeek
                }
            }
        });

        const generatedFlights = [];

        for (const schedule of schedules) {
            const dateStr = date.toISOString().split('T')[0];
            const departureDate = new Date(`${dateStr}T${schedule.departureTime}:00Z`);

            let returnDate = null;
            if (schedule.returnTime) {
                const retDate = new Date(date);
                // Use UTC methods for return leg date calculations
                retDate.setUTCDate(date.getUTCDate() + 7);
                const retDateStr = retDate.toISOString().split('T')[0];
                returnDate = new Date(`${retDateStr}T${schedule.returnTime}:00Z`);
            }

            // Check if flight instance already exists
            let flight = await prisma.flight.findFirst({
                where: {
                    flightNumber: schedule.flightNumber,
                    departureDate: departureDate
                }
            });

            if (!flight) {
                try {
                    flight = await prisma.flight.create({
                        data: {
                            flightNumber: schedule.flightNumber,
                            airline: schedule.airline,
                            from: schedule.from,
                            to: schedule.to,
                            departureDate,
                            returnDate,
                            price: schedule.price,
                            status: 'ON_TIME',
                            firstClassRows: schedule.firstClassRows ?? 3,
                            businessRows: schedule.businessRows ?? 3,
                            premiumEconomyRows: schedule.premiumEconomyRows ?? 4,
                            economyRows: schedule.economyRows ?? 20,
                            seatPattern: schedule.seatPattern ?? 'ABC-DEF'
                        }
                    });
                } catch (error) {
                    // Gracefully handle concurrent insertion race condition (Prisma unique constraint error P2002)
                    if (error && typeof error === 'object' && 'code' in error && error.code === 'P2002') {
                        flight = await prisma.flight.findFirst({
                            where: {
                                flightNumber: schedule.flightNumber,
                                departureDate: departureDate
                            }
                        });
                    } else {
                        throw error;
                    }
                }
            }

            if (flight) {
                generatedFlights.push(flight);
            }
        }

        return generatedFlights;
    }
}

